  var calls = 0;
  return (body) {
    final sw = Stopwatch()..start();
    body();
    sw.stop();
    calls++;
    return sw.elapsedMicroseconds +
        (spiked.contains(calls) ? (spikeMs * 1000).round() : 0);
  };
