final bestCase = ratios.reduce(min);  // uncontended upper-bound estimate
final worstCase = ratios.reduce(max);
expect(bestCase, lessThan(3.2));  // not superlinear under best conditions
expect(worstCase, greaterThan(1.5)); // still meaningfully grows (linear ~2x)
