blocks.text:
import 'dart:math';

import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';
import 'package:test/test.dart';

/// Perf contracts for [wrapAnsiLine] (gh-1496): the transcript wrap pass
/// was the #1 self-time hotspot — 1084s self over 84 profiled calls,
/// mean 12.9s (instrumented) — because the tokenizer paid a regex match,
/// a String allocation and a width measurement PER VISIBLE CELL. The
/// rewrite batches same-width rune runs into single tokens (one substring
/// + one carried width per run, SGR state machine unchanged) and drops the
/// double width measurement in flushWord.
///
/// Bounds follow the gh-1357 rule: absolute budgets carry generous
/// headroom over local medians (CI runners jitter; a bound the fix sits
/// at is noise, not a gate), and the growth-shape asserts are the real
/// regression guard — a per-row rescan or per-cell allocation coming back
/// shows up as a superlinear doubling ratio long before any absolute
/// budget trips.
final _rng = Random(1496);

const _words = [
  'lorem',
  'ipsum',
  'dolor',
  'sit',
  'amet',
  'consectetur',
  'adipiscing',
  'elit',
  'sed',
  'do',
  'eiusmod',
  'tempor',
  'incididunt',
  'ut',
  'labore',
  'et',
  'dolore',
  'magna',
  'aliqua',
];

/// [_cells] visible cells of ASCII prose (the dominant transcript shape).
String asciiProse(int cells) {
  final buf = StringBuffer();
  while (buf.length < cells) {
    buf.write(_words[_rng.nextInt(_words.length)]);
    buf.write(' ');
  }
  return buf.toString().substring(0, cells);
}

/// [_cells] cells of CJK prose (every rune 2 cells, exercises the rune
/// classification path — no ASCII batching possible).
String cjkProse(int cells) {
  final buf = StringBuffer();
  final half = cells ~/ 2;
  var i = 0;
  while (i < half) {
    buf.writeCharCode(0x4e00 + _rng.nextInt(2000));
    i++;
    if (i % 17 == 0) buf.write(' ');
  }
  return buf.toString();
}

/// [_cells] cells in ONE word (exercises the hard-cut slice path).
String oneGiantWord(int cells) => 'x' * cells;

/// Median wrap time over [runs] executions (one untimed warm-up first).
double medianWrapMs(String line, int width, {int runs = 5}) {
  wrapAnsiLine(line, width); // JIT warm-up, untimed
  final times = List<double>.filled(runs, 0);
  for (var i = 0; i < runs; i++) {
    final sw = Stopwatch()..start();
    wrapAnsiLine(line, width);
    sw.stop();
    times[i] = sw.elapsedMicroseconds / 1000.0;
  }
  times.sort();
  return times[runs ~/ 2];
}

/// Growth-shape contract: doubling the input must not more than [maxRatio]
/// the median time. Linear wraps measure ~2x here; the old quadratic
/// candidates (re-scan per emitted row) measure ~4x+. 3.2 sits between
/// with room for CI scheduler jitter on both sides.
void expectLinearGrowth(
  String Function(int cells) build,
  int baseCells,
  String label,
) {
  final small = medianWrapMs(build(baseCells), 80);
  final doubled = medianWrapMs(build(baseCells * 2), 80);
  final ratio = doubled / small;
  expect(
    ratio,
    lessThan(3.2),
    reason:
        '$label wrap is superlinear in input size: '
        '$baseCells cells = ${small.toStringAsFixed(2)}ms, '
        '${baseCells * 2} cells = ${doubled.toStringAsFixed(2)}ms '
        '(ratio ${ratio.toStringAsFixed(2)}x)',
  );
}

void main() {
  test('1M visible ASCII cells wrap in < 100ms (median, warm VM)', () {
    // The gh-1496 acceptance bar. Pre-fix this measured ~117ms (6.9x the
    // post-fix median) — the bound pins the constant-factor win, not just
    // the absence of quadratic growth.
    final ms = medianWrapMs(asciiProse(1000000), 80);
    expect(ms, lessThan(100), reason: 'took ${ms.toStringAsFixed(1)}ms');
  });

  test('1M-cell single word hard-cuts in < 100ms (median, warm VM)', () {
    // The hard-cut slice path (a word longer than the width).
    final ms = medianWrapMs(oneGiantWord(1000000), 80);
    expect(ms, lessThan(100), reason: 'took ${ms.toStringAsFixed(1)}ms');
  });

  test('wrap time grows linearly: ASCII prose, 2x input <= 3.2x time', () {
    expectLinearGrowth(asciiProse, 100000, 'ASCII prose');
  });

  test('wrap time grows linearly: CJK prose, 2x input <= 3.2x time', () {
    // CJK walks the wide-rune tables per rune — no ASCII batching — so a
    // regression that re-measures or re-scans per emitted row would show
    // here first.
    expectLinearGrowth(cjkProse, 100000, 'CJK prose');
  });

  test('wrap time grows linearly: hard-cut single word, 2x <= 3.2x', () {
    expectLinearGrowth(oneGiantWord, 100000, 'single word');
  });

  test('wrapped output stays contract-clean at scale', () {
    // Cheap correctness anchor next to the timings: rows never exceed the
    // width in visible cells and reassemble to the source (the properties
    // ansi_markdown_test.dart pins on small inputs, checked once on a
    // large one so a fast-but-wrong rewrite cannot pass this file).
    final line = asciiProse(200000);
    final rows = wrapAnsiLine(line, 80);
    var reassembled = 0;
    for (final row in rows) {
      expect(row.length, lessThanOrEqualTo(80));
      reassembled += row.length;
    }
    // Reassembly reproduces the visible text minus dropped edge spaces.
    expect(reassembled, greaterThanOrEqualTo(line.length - rows.length));
  });
}

Now let me understand the timing issue. The failing test is the ASCII prose growth test at baseCells=1000. On a contended runner, the small (100k) measurement might be e.g. 1-2ms; a scheduling hiccup of a few ms inflates either the small or doubled measurement, making ratio > 3.2.

Also note: the ratio guard `lessThan(3.2)` fails if `small` is anomalously tiny (contention hits only the doubled measurement) or `doubled` is inflated. On a contended runner, GC pause could hit during doubled measurement.

Ticket goal options:
1. Pin calibration baseline measured on the same run with K x self-baseline — that's already what ratio does. The issue is noise.
2. Retry with warmup.
3. Move to dedicated perf lane.

The best minimal fix: make `expectLinearGrowth` retry-based with min-of-ratios and more warmup. Since contention only adds time, taking the minimum ratio over N attempts approaches the uncontended ratio. Also increase runs per median to reduce noise.

For TDD: I need a reproduction test that fails. This is inherently a flake — deterministic reproduction is impossible. But I can write a test that verifies the hermeticity property of the harness itself: e.g., that `expectLinearGrowth`-style measurement retries and takes min, so a single inflated measurement doesn't fail. A common approach: test the measurement helper with an injected noise function / clock seam. But adding a clock seam to the perf test might be over-engineering.

Alternative: restructure the measurement into a testable function `measureGrowthRatio` that accepts a `measure` callback, and write a unit test that simulates a contended runner (occasional huge outliers) and asserts the final ratio stays under threshold. That gives a deterministic RED test: with current code (single attempt, no retry), simulated contention fails; with fix (retry + min), it passes.

But wait — the instructions say "NEVER fix code without a failing reproduction test first". For flake hardening, a reasonable reproduction: simulate contention on the measurement function and assert the test harness is robust. Let me design:

```dart
/// Growth-shape contract ...
double growthRatio(String Function(int) build, int baseCells, {int attempts = 3}) {
  double best = double.infinity;
  for (var a = 0; a < attempts; a++) {
    final small = medianWrapMs(build(baseCells), 80);
    final doubled = medianWrapMs(build(baseCells * 2), 80);
    best = min(best, doubled / small);
  }
  return best;
}
```

Hmm, but min of ratios across attempts — each attempt measures both sizes; contention hitting only one side inflates that attempt's ratio; the min over attempts is robust because with multiple attempts, at least one attempt likely has both sides clean. Probability all 3 attempts contaminated is low.

Even better: the regression guard could be two-sided — not only assert doubling isn't superlinear (upper bound) but also that the doubled is actually bigger (lower bound) so the test stays meaningful (AC2). The ticket says "the linear-growth property is still meaningfully asserted". Adding a lower bound (e.g., ratio > 1.2) would guard against a degenerate "always pass" fix. Actually min-of-attempts with a lower bound: take max of small measurements and min of doubled measurements? Let's think:

For a robust regression guard:
- superlinear detection: need upper bound on doubled/small. Contention inflates times, so use min ratio across attempts.
- meaningful detection: need to detect if the code got FASTER than linear? Actually a regression would make it slower. The lower bound guards against trivial passes e.g. if measurement always returns ~equal times due to some caching. A lower bound of e.g. 1.5 (linear = 2.0 expected) with max-of-ratios? Contention deflates... contention can also hit the small measurement making ratio appear small. So for lower bound use max ratio across attempts.

So:
```dart
final ratios = <double>[];
for (attempts) { ratios.add(doubled/small); }
final bestCase = ratios.reduce(min);  // uncontended upper-bound estimate
final worstCase = ratios.reduce(max);
expect(bestCase, lessThan(3.2));  // not superlinear under best conditions
expect(worstCase, greaterThan(1.5)); // still meaningfully grows (linear ~2x)
```

Now, deterministic reproduction test. To make it testable without real time, extract a pure helper:

```dart
double robustGrowthRatio({
  required double Function() measureRatio, // one attempt
  required int attempts,
}) {
  var min = double.infinity, max = 0.0;
  for (...) { final r = measureRatio(); ... }
  return min;
}
```

Then a test injects a `measureRatio` that returns a huge outlier on the first attempts and clean 2.0 later, asserting the result is 2.0 (fails with current single-attempt logic since current code calls measureRatio once... well, the helper doesn't exist yet).

Hmm, but TDD RED requires the test fail before fix. If I write a new helper test where the helper doesn't exist, the test fails to compile — that counts as RED? Compiling failure is a fail, yes, but a better reproduction would exercise existing behavior. Alternatively, the reproduction test can exercise `expectLinearGrowth` indirectly... it would be flaky by nature.

