/// measures ~4x+ under any contention and still fails), while the max
/// ratio must clear [minGrowthRatio] so a degenerate flat measurement
/// cannot pass (AC2: the regression guard stays meaningful).
void expectLinearGrowth(
  String Function(int cells) build,
  int baseCells,
  String label, {
  int attempts = 3,
  double maxLinearRatio = 3.2,
  double minGrowthRatio = 1.5,
  ElapsedUs? elapsedUs,
}) {
