    worst,
    greaterThan(minGrowthRatio),
    reason: '$label doubling ratio never exceeded ${minGrowthRatio}x '
        '(${worst.toStringAsFixed(2)}x across $attempts attempts) — the '
        'measurement is degenerate and asserts nothing',
  );
}
