import 'dart:math';

import 'package:flutter_agent_harness/src/cli/ansi_markdown.dart';
import 'package:test/test.dart';

/// Perf contracts for [wrapAnsiLine] (gh-1496): the transcript wrap pass
/// was the #1 self-time hotspot — 1084s self over 84 profiled calls,
/// mean 12.9s (instrumented) — because the tokenizer paid a regex match,
/// a String allocation and a width measurement PER VISIBLE CELL. The
/// rewrite batches same-width rune runs into single tokens (one substring
/// + one carried width per run, SGR state machine unchanged) and drops the
/// double width measurement in flushWord.

{"command":"dart test --exclude-tags integration --file-reporter=json:/tmp/discovery.json -n 'gh-1532' > /dev/null 2>&1; python3 -c "
import json
names={}
for line in open('/tmp/discovery.json'):
    e=json.loads(line)
    if e.get('type')=='testStart': names[e['test']['id']]=e['test']['name']
    elif e.get('type')=='testDone': print(e['result'],'-',names.get(e['testID'],'')[:100])
"","timeout":600}

{"command":"python3 -c "
import json
lines=open('/tmp/cli_run.json').read().splitlines()
d=json.loads(lines[0])
tests=[t for s in d['suites'] for g in s['groups'] for t in g['tests']]
print('total tests:',len(tests))
for t in tests:
    if '1M' in t['name'] or 'grows linearly' in t['name'] or 'gh-1532' in t['name']:
        print(t['result'],'-',t['name'][:100])
""}

